/* Conceptual PoC for NULL pointer dereference in DPB cleanup */
#include <stdio.h>

typedef struct {
    void *buf[1];
} Picture;

typedef struct {
    Picture *f; // NULL when slot is unused
} DPBEntry;

typedef struct {
    DPBEntry DPB[16];
} H264Context;

void release_unused_pictures(H264Context *h) {
    for (int i = 0; i < 16; i++) {
        /* VULNERABILITY: Missing NULL check on h->DPB[i].f */
        /* Unused DPB slots have f == NULL. Dereferencing it to access buf[0] */
        /* triggers a segmentation fault (NULL pointer dereference). */
        h->DPB[i].f->buf[0] = NULL;
    }
}

int main() {
    H264Context ctx = {0}; // Initializes all DPB entries to NULL
    release_unused_pictures(&ctx); // Crashes on first iteration
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <string.h>

/* Simulates avio_get_str: returns the number of bytes that WOULD be read
   if the buffer were large enough, regardless of the actual buffer size. */
uint64_t mock_avio_get_str(const char *input, uint64_t buffer_size) {
    (void)buffer_size;
    return strlen(input) + 1;
}

void demonstrate_underflow(uint64_t len) {
    char place[16];
    const char *malformed_data = "This_string_exceeds_the_buffer_size_limit";

    /* 1. Parser returns a length larger than our buffer/limit */
    uint64_t returned_len = mock_avio_get_str(malformed_data, sizeof(place));

    /* 2. Unsigned subtraction causes wrap-around (underflow)
       Since returned_len > len, the result wraps to a very large positive number. */
    len -= returned_len;

    /* 3. Subsequent bounds checks are bypassed because len is now huge */
    if (len < 1 || len < 12) {
        printf("Bounds check triggered (expected for valid data)\n");
    } else {
        printf("VULNERABILITY: Unsigned underflow bypassed bounds check. len=%lu\n", (unsigned long)len);
    }
}

int main() {
    uint64_t atom_size = 10;
    demonstrate_underflow(atom_size);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

typedef struct {
    int32_t sb_cols;
    int32_t sb_rows;
    uint8_t *extradata;
} VP9Context;

void vulnerable_calculation(VP9Context *s) {
    // Vulnerable line: 32-bit signed integer overflow
    // Large dimensions cause the multiplication to exceed INT32_MAX
    // and wrap around to a negative or unexpectedly small value.
    int32_t sz = 64 * s->sb_cols * s->sb_rows;

    // Pointer arithmetic uses the overflowed size
    // A negative sz shifts the pointer backwards, pointing before the buffer
    // A wrapped positive sz points to an incorrect offset
    uint8_t *target = s->extradata + sz;

    printf("Dimensions: %dx%d\n", s->sb_cols, s->sb_rows);
    printf("Expected size: %lld bytes\n", (long long)64LL * s->sb_cols * s->sb_rows);
    printf("Overflowed size (sz): %d bytes\n", sz);
    printf("Buffer base: %p\n", (void*)s->extradata);
    printf("Calculated write target: %p\n", (void*)target);

    // Conceptual out-of-bounds write (disabled for safety)
    // memcpy(target, source_data, sz);
}

int main(void) {
    VP9Context ctx = {0};
    ctx.extradata = (uint8_t*)malloc(1024);

    // Malicious dimensions crafted to trigger 32-bit signed overflow
    // 64 * 0x10000 * 0x10000 = 0x40000000000 (exceeds 32-bit range)
    // Wraps to 0 in 32-bit signed arithmetic, causing target == base
    ctx.sb_cols = 0x10000;
    ctx.sb_rows = 0x10000;

    vulnerable_calculation(&ctx);

    free(ctx.extradata);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct { int16_t x, y; uint8_t ref, flags; } MvField;

// Simulates av_buffer_pool_init allocation logic
void* simulated_pool_init(int size) {
    printf("[+] Requested size: %d bytes\n", size);
    // Vulnerability: small/negative size due to overflow leads to undersized allocation
    return malloc(size > 0 ? size : 16);
}

int main() {
    // Crafted SPS parameters that trigger 32-bit signed integer overflow
    int32_t min_pu_width  = 0x10000;
    int32_t min_pu_height = 0x10000;

    // 0x10000 * 0x10000 = 0x100000000, which overflows int32_t to 0
    int32_t min_pu_size = min_pu_width * min_pu_height;
    printf("[-] min_pu_size after overflow: %d\n", min_pu_size);

    // Propagates to allocation size calculation
    int32_t pool_size = min_pu_size * (int32_t)sizeof(MvField);
    printf("[-] pool_size after overflow: %d bytes\n", pool_size);

    // Allocates undersized buffer
    void* pool = simulated_pool_init(pool_size);

    // Educational note: Decoder later writes min_pu_size elements,
    // exceeding the actual allocated memory -> heap buffer overflow
    printf("[!] Mismatch: Allocated %d bytes vs Required %ld bytes\n",
           pool_size, (long)min_pu_size * sizeof(MvField));

    free(pool);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Simplified structure mimicking VP9Frame
struct extradata {
    char data[64];
};

struct vp9_frame {
    struct extradata *extradata;
    char *mv;           // Dangling pointer points into extradata->data
    void *hwaccel_picture_private;
};

// Simulates allocation and initialization
struct vp9_frame* vp9_frame_alloc() {
    struct vp9_frame *f = malloc(sizeof(*f));
    f->extradata = malloc(sizeof(*f->extradata));
    strcpy(f->extradata->data, "motion_vector_data");
    f->mv = f->extradata->data; // mv points into extradata
    f->hwaccel_picture_private = NULL;
    return f;
}

// Vulnerable unreference function
void vp9_frame_unref(struct vp9_frame *f) {
    // Frees extradata, which contains the memory mv points to
    free(f->extradata);
    // BUG: f->mv is NOT set to NULL here, leaving a dangling pointer
    // f->mv = NULL; // Missing null-assignment

    // Correctly nullifies another pointer (as per hypothesis)
    f->hwaccel_picture_private = NULL;
}

// Simulates later access during decode/reuse
void process_motion_vectors(struct vp9_frame *f) {
    // Exploit mechanism: f->mv is accessed without checking if it's valid
    // Since it wasn't NULLed, it still holds the old address
    // Dereferencing it accesses freed memory (Use-After-Free)
    if (f->mv) { // In real code, this check might be absent or bypassed
        printf("Accessing stale pointer: %s\n", f->mv);
    }
}

int main() {
    struct vp9_frame *frame = vp9_frame_alloc();
    printf("Initial mv pointer: %p\n", (void*)frame->mv);

    vp9_frame_unref(frame);
    printf("After unref, mv pointer: %p (dangling)\n", (void*)frame->mv);

    // Simulate frame reuse or concurrent access before reallocation
    process_motion_vectors(frame);

    free(frame);
    return 0;
}
